solution.code:
#include <stdio.h>

int main() {
    int a[] = {20, 20, 10, 5};
    int first = -1, second = -1;
    for (int i = 0; i < 4; i++) {
        if (a[i] > first) {
            second = first;
            first = a[i];
        } else if (a[i] > second && a[i] != first) {
            second = a[i];
        }
    }
    printf("Second largest: %d\n", second);
    return 0;
}
